'use strict';

const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  createCh9329Input,
  createNanoKvmInput,
  listDevices,
  probeInputDevice
} = require('..');

const execFileAsync = promisify(execFile);

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const options = {
    kind: process.env.MOVE_TRACE_KIND || 'both',
    ch9329Port: process.env.CH9329_PORT || '',
    nanoKvmPort: process.env.NANOKVM_PORT || '',
    dx: Number(process.env.MOVE_TRACE_DX || 300),
    dy: Number(process.env.MOVE_TRACE_DY || 0),
    maxStepPx: Number(process.env.MOVE_TRACE_MAX_STEP_PX || 0),
    stepDelayMs: Number(process.env.MOVE_TRACE_STEP_DELAY_MS || -1),
    tolerancePx: Number(process.env.MOVE_TRACE_TOLERANCE_PX || 0),
    moveTimeoutMs: Number(process.env.MOVE_TRACE_TIMEOUT_MS || 2500),
    settleMs: Number(process.env.MOVE_TRACE_SETTLE_MS || 250),
    pauseMs: Number(process.env.MOVE_TRACE_PAUSE_MS || 800),
    warpStart: process.env.MOVE_TRACE_WARP_START !== '0',
    returnToStart: process.env.MOVE_TRACE_RETURN !== '0'
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];
    if (arg === '--kind' && next) {
      options.kind = next;
      index += 1;
    } else if (arg === '--ch9329-port' && next) {
      options.ch9329Port = next;
      index += 1;
    } else if (arg === '--nanokvm-port' && next) {
      options.nanoKvmPort = next;
      index += 1;
    } else if (arg === '--dx' && next) {
      options.dx = Number(next);
      index += 1;
    } else if (arg === '--dy' && next) {
      options.dy = Number(next);
      index += 1;
    } else if (arg === '--max-step' && next) {
      options.maxStepPx = Number(next);
      index += 1;
    } else if (arg === '--delay' && next) {
      options.stepDelayMs = Number(next);
      index += 1;
    } else if (arg === '--tolerance' && next) {
      options.tolerancePx = Number(next);
      index += 1;
    } else if (arg === '--timeout' && next) {
      options.moveTimeoutMs = Number(next);
      index += 1;
    } else if (arg === '--no-warp') {
      options.warpStart = false;
    } else if (arg === '--no-return') {
      options.returnToStart = false;
    }
  }

  if (!['both', 'ch9329', 'nanokvm'].includes(options.kind)) options.kind = 'both';
  if (!Number.isFinite(options.dx)) options.dx = 300;
  if (!Number.isFinite(options.dy)) options.dy = 0;
  if (!Number.isFinite(options.moveTimeoutMs) || options.moveTimeoutMs <= 0) options.moveTimeoutMs = 2500;
  if (!Number.isFinite(options.settleMs) || options.settleMs < 0) options.settleMs = 250;
  if (!Number.isFinite(options.pauseMs) || options.pauseMs < 0) options.pauseMs = 800;

  return options;
}

async function getCursorPosFromSystem() {
  if (process.platform !== 'darwin') {
    throw new Error(`cursor sampling is currently implemented for macOS only, got ${process.platform}`);
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let p = NSEvent.mouseLocation',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'print("\\(Int(p.x)),\\(Int(frame.height - p.y))")'
    ].join('\n')
  ]);
  const [x, y] = stdout.trim().split(',').map((value) => Number(value));
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new Error(`invalid cursor output: ${stdout}`);
  }
  return { x, y };
}

async function warpCursorToMainScreenCenter() {
  if (process.platform !== 'darwin') {
    return;
  }

  await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'import CoreGraphics',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'let point = CGPoint(x: frame.midX, y: frame.midY)',
      'CGWarpMouseCursorPosition(point)',
      'CGAssociateMouseAndMouseCursorPosition(boolean_t(1))'
    ].join('\n')
  ]);
}

async function detectPort(kind, explicitPort) {
  if (explicitPort) {
    const result = await probeInputDevice(explicitPort, {
      kind,
      probeTimeoutMs: 1500,
      logger: null
    });
    if (!result.available) {
      throw new Error(`${kind} probe failed on ${explicitPort}: ${result.reason || 'unknown error'}`);
    }
    return result.portPath;
  }

  const devices = await listDevices();
  for (const device of devices.filter((item) => item.isUsbLike)) {
    const result = await probeInputDevice(device.path, {
      kind,
      probeTimeoutMs: 1500,
      logger: null
    });
    if (result.available) {
      return result.portPath;
    }
  }

  throw new Error(`no available ${kind} port found`);
}

function createInput(kind, portPath, options, traceLabel) {
  const inputOptions = {
    portPath,
    baudRate: kind === 'ch9329' ? 9600 : 57600,
    moveTimeoutMs: options.moveTimeoutMs,
    logger: null,
    onMoveStep: (event) => {
      console.log(JSON.stringify({
        event: 'move-step',
        label: traceLabel.current,
        ...event
      }));
    }
  };

  if (Number.isFinite(options.maxStepPx) && options.maxStepPx > 0) {
    inputOptions.maxStepPx = options.maxStepPx;
  }
  if (Number.isFinite(options.stepDelayMs) && options.stepDelayMs >= 0) {
    inputOptions.stepDelayMs = options.stepDelayMs;
  }
  if (Number.isFinite(options.tolerancePx) && options.tolerancePx > 0) {
    inputOptions.tolerancePx = options.tolerancePx;
  }

  return kind === 'ch9329'
    ? createCh9329Input(inputOptions)
    : createNanoKvmInput(inputOptions);
}

async function runMoveCase(input, kind, portPath, label, target, options, traceLabel) {
  traceLabel.current = label;
  const before = await getCursorPosFromSystem();
  let status = 'ok';
  let error = '';

  try {
    await input.moveTo(target.x, target.y, getCursorPosFromSystem);
  } catch (moveError) {
    status = 'failed';
    error = moveError?.message || String(moveError);
  }

  await sleep(options.settleMs);
  const after = await getCursorPosFromSystem();
  const result = {
    event: 'move-result',
    kind,
    portPath,
    label,
    status,
    before,
    target,
    after,
    actual: {
      dx: after.x - before.x,
      dy: after.y - before.y
    },
    error
  };
  console.log(JSON.stringify(result));
  return result;
}

async function measureDevice(kind, portPath, options) {
  if (options.warpStart) {
    await warpCursorToMainScreenCenter();
    await sleep(options.settleMs);
  }

  const traceLabel = { current: 'forward' };
  const input = createInput(kind, portPath, options, traceLabel);
  await input.connect();
  try {
    const start = await getCursorPosFromSystem();
    const target = { x: start.x + options.dx, y: start.y + options.dy };
    const forward = await runMoveCase(input, kind, portPath, 'forward', target, options, traceLabel);

    let back = null;
    if (options.returnToStart) {
      await sleep(options.pauseMs);
      back = await runMoveCase(input, kind, portPath, 'return', start, options, traceLabel);
    }

    return {
      kind,
      portPath,
      start,
      requested: { dx: options.dx, dy: options.dy },
      forward,
      return: back
    };
  } finally {
    await input.disconnect();
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const kinds = options.kind === 'both' ? ['ch9329', 'nanokvm'] : [options.kind];
  const ports = {};

  for (const kind of kinds) {
    ports[kind] = await detectPort(
      kind,
      kind === 'ch9329' ? options.ch9329Port : options.nanoKvmPort
    );
  }

  console.log(JSON.stringify({
    event: 'move-trace-start',
    options,
    ports
  }, null, 2));

  const results = [];
  for (const kind of kinds) {
    console.log(JSON.stringify({ event: 'device-start', kind, portPath: ports[kind] }));
    results.push(await measureDevice(kind, ports[kind], options));
    await sleep(options.pauseMs);
  }

  console.log(JSON.stringify({ event: 'move-trace-complete', results }, null, 2));
}

main().catch((error) => {
  console.error('[move-to-trace] failed:', error);
  process.exitCode = 1;
});
